import{_ as t,o,c as a,ag as s}from"./chunks/framework.B2Q7dRKp.js";const f=JSON.parse('{"title":"Accounts & Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accounts.md","filePath":"guide/accounts.md","lastUpdated":1776508966000}'),n={name:"guide/accounts.md"};function c(i,e,r,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="accounts-sessions" tabindex="-1">Accounts &amp; Sessions <a class="header-anchor" href="#accounts-sessions" aria-label="Permalink to &quot;Accounts &amp; Sessions&quot;">​</a></h1><p>Cookies are persisted per account in <code>sessions/</code> next to the exe. Each file is keyed by a hash of the email.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ul><li><strong>First run</strong> — full login, cookies saved.</li><li><strong>Subsequent runs</strong> — cookies loaded and validated. If the server rejects (expired), the bot logs in again.</li></ul><h2 id="when-to-clear" tabindex="-1">When to clear <a class="header-anchor" href="#when-to-clear" aria-label="Permalink to &quot;When to clear&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Action</th></tr></thead><tbody><tr><td>Password changed on the site</td><td>Delete <code>sessions/&lt;site&gt;_&lt;hash&gt;.json</code></td></tr><tr><td>Account locked / 2FA triggered</td><td>Delete the file, log in manually once, re-run</td></tr><tr><td>Clean slate for debugging</td><td>Delete the whole <code>sessions/</code> folder</td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>The <code>sessions/</code> folder contains <strong>live logged-in cookies</strong>. Anyone with the folder can impersonate your accounts on the affected sites. Do not share, back up to public clouds, or commit.</p>',8)])])}const g=t(n,[["render",c]]);export{f as __pageData,g as default};
